public DMFExecutionId importFromPackageV2(SharedServiceUnitURL packageUrl,
                                        DMFDefinitionGroupName sourceDefinitionGroupId,
                                        DMFExecutionId sourceExecutionId,
                                        boolean execute,
                                        boolean overwrite,
                                        DataAreaId legalEntityId,
                                        BatchGroupId importBatchGroupId,
                                        boolean failOnError,
                                        SharedServiceUnitFileID packageFileId,
                                        boolean _processIntegrationBridgeData,
                                        boolean _export,
                                        boolean internalCall,
                                        boolean _runAsyncWithoutBatch,
                                        int _thresholdToRunInBatch,
                                        int  _previewCount,
                                        str _messageId)
{
    ISMTelemetryDMF telemetry = new ISMTelemetryDMF();
    telemetry.addRuntimeProperty("sourceDefinitionGroupId", sourceDefinitionGroupId);
    telemetry.addRuntimeProperty("sourceExecutionId", sourceExecutionId);
    telemetry.addRuntimeProperty("execute", any2Str(execute));
    telemetry.addRuntimeProperty("overwrite", any2Str(overwrite));
    telemetry.addRuntimeProperty("legalEntityId", legalEntityId);
    telemetry.addRuntimeProperty("importBatchGroupId", importBatchGroupId);
    telemetry.addRuntimeProperty("failOnError", any2Str(failOnError));
    telemetry.addRuntimeProperty("packageFileId", packageFileId);
    telemetry.addRuntimeProperty("_processIntegrationBridgeData", any2Str(_processIntegrationBridgeData));
    telemetry.addRuntimeProperty("_export", any2Str(_export));
    telemetry.addRuntimeProperty("internalCall", any2Str(internalCall));
    telemetry.addRuntimeProperty("_runAsyncWithoutBatch", any2Str(_runAsyncWithoutBatch));
    telemetry.addRuntimeProperty("_thresholdToRunInBatch", any2Str(_thresholdToRunInBatch));
    telemetry.addRuntimeProperty("_previewCount", any2Str(_previewCount));
    telemetry.addRuntimeProperty("_messageId", _messageId);


    DMFExecutionId executionId = next importFromPackageV2(packageUrl, sourceDefinitionGroupId, sourceExecutionId, execute, overwrite, legalEntityId, importBatchGroupId, failOnError, packageFileId, _processIntegrationBridgeData, _export, internalCall, _runAsyncWithoutBatch, _thresholdToRunInBatch, _previewCount, _messageId);

    telemetry.processEvent(ISMTelemetryEventNames::DMFImport);

    this.processDetailedTelemetry(executionId, sourceDefinitionGroupId);

    return executionId;
}

private void processDetailedTelemetry(DMFExecutionId _executionId, DMFDefinitionGroupName _definitionGroup)
{

    DMFDefinitionGroupExecution         dmfDefinitionGroupExecution;//         = DMFDefinitionGroupExecution::find(_definitionGroupExecution.DefinitionGroup,_definitionGroupExecution.Entity,_definitionGroupExecution.ExecutionId);
    DMFDefinitionGroupExecutionHistory  dmfDefinitionGroupExecutionHistory; // = DMFDefinitionGroupExecutionHistory::find(_definitionGroup, dmfDefinitionGroupExecution.Entity,
    ////DictTable       dictTable;
    //SysDictTable                stagingDictTable;
    //Query   		   query;
    //QueryRun                   queryRun;
    //QueryBuildDataSource        qbds;
    //QueryBuildRange         qbr,qbr2, qbr3;


    while select dmfDefinitionGroupExecutionHistory
        where dmfDefinitionGroupExecutionHistory.DefinitionGroup == _definitionGroup
        && dmfDefinitionGroupExecutionHistory.ExecutionId == _executionId
    {
       // DMFEntity entity = DMFEntity::find(dmfDefinitionGroupExecution.Entity);

        ISMTelemetryDMF telemetry = new ISMTelemetryDMF();
       // telemetry.addRuntimeProperty(ISMTelemetryProperties::ElapsedMilliseconds, int642Str(DateTimeUtil::getDifference(executionEndTime, executionStartTime)));
        telemetry.addRuntimeProperty(ISMTelemetryProperties::DefinitionGroup, dmfDefinitionGroupExecutionHistory.DefinitionGroup);
        telemetry.addRuntimeProperty(ISMTelemetryProperties::Entity, dmfDefinitionGroupExecutionHistory.Entity);
        telemetry.addRuntimeProperty(ISMTelemetryProperties::ExecutionId,dmfDefinitionGroupExecutionHistory.ExecutionId);
        telemetry.addRuntimeProperty(ISMTelemetryProperties::NoOfRecords, int2Str(dmfDefinitionGroupExecutionHistory.NoOfRecords));
        telemetry.addRuntimeProperty(ISMTelemetryProperties::NumOfTargetNew,int2Str(dmfDefinitionGroupExecutionHistory.NumOfTargetNew));
        telemetry.addRuntimeProperty(ISMTelemetryProperties::NumOfTargetUpdated, int2Str(dmfDefinitionGroupExecutionHistory.NumOfTargetUpdated));
        telemetry.addRuntimeProperty(ISMTelemetryProperties::FILEPATH, dmfDefinitionGroupExecutionHistory.FILEPATH);
        telemetry.addRuntimeProperty(ISMTelemetryProperties::FILETYPE, int2Str(dmfDefinitionGroupExecutionHistory.FILETYPE));
        telemetry.addRuntimeProperty(ISMTelemetryProperties::NUMOFSTAGINGNEW, int2Str(dmfDefinitionGroupExecutionHistory.NUMOFSTAGINGNEW));
        telemetry.addRuntimeProperty(ISMTelemetryProperties::NUMOFTARGETNEW, int2Str(dmfDefinitionGroupExecutionHistory.NUMOFTARGETNEW));
        telemetry.addRuntimeProperty(ISMTelemetryProperties::NOOFTHREADS, int2Str(dmfDefinitionGroupExecutionHistory.NOOFTHREADS));
        telemetry.addRuntimeProperty(ISMTelemetryProperties::SEQUENCE, int2Str(dmfDefinitionGroupExecutionHistory.SEQUENCE));
        telemetry.addRuntimeProperty(ISMTelemetryProperties::TARGETSTATUS, int2Str(dmfDefinitionGroupExecutionHistory.TARGETSTATUS));
        telemetry.addRuntimeProperty(ISMTelemetryProperties::STAGINGSTATUS, int2Str(dmfDefinitionGroupExecutionHistory.STAGINGSTATUS));
        telemetry.addRuntimeProperty(ISMTelemetryProperties::STAGINGERRORCOUNT, int2Str(dmfDefinitionGroupExecutionHistory.STAGINGERRORCOUNT));
        telemetry.addRuntimeProperty(ISMTelemetryProperties::TARGETERRORCOUNT, int2Str(dmfDefinitionGroupExecutionHistory.TARGETERRORCOUNT));
        telemetry.addRuntimeProperty(ISMTelemetryProperties::NUMOFTARGETDELETED, int2Str(dmfDefinitionGroupExecutionHistory.NUMOFTARGETDELETED));
        telemetry.addRuntimeProperty(ISMTelemetryProperties::ERRORFILEID, dmfDefinitionGroupExecutionHistory.ERRORFILEID);
        telemetry.addRuntimeProperty(ISMTelemetryProperties::CREATEDDATETIME, date2Str(DateTimeUtil::date(dmfDefinitionGroupExecutionHistory.CREATEDDATETIME),1,1,1,1,1,1));
        telemetry.processEvent(ISMTelemetryEventNames::DMFDefinitionGroupExecutionHistory);




    }
}
